import { beforeAll, describe, expect, it } from 'bun:test'
import { TestApp } from '@guren/testing'
import app from '../src/app.js'
import { getDatabase } from '../config/database.js'
import { Post } from '../app/Models/Post.js'

describe('scheduled posts', () => {
  let http: TestApp

  beforeAll(async () => {
    http = await TestApp.fromApp(app)
  })

  it('rejects a publishAt that is not a date', async () => {
    await http.query('/posts/search', { keywords: [] }).assertStatus(422)
    const { PostPayloadSchema } = await import('../app/Http/Validators/PostValidator.js')
    const base = { title: 't', excerpt: 'e', body: 'b' }
    expect(PostPayloadSchema.safeParse({ ...base, publishAt: 'next tuesday' }).success).toBe(false)
    expect(PostPayloadSchema.parse({ ...base }).publishAt).toBeNull()
    expect(PostPayloadSchema.parse({ ...base, publishAt: '2026-10-01T09:00:00.000Z' }).publishAt).toBe(
      '2026-10-01T09:00:00.000Z',
    )
  })

  it('hides future posts from guests in search', async () => {
    void getDatabase
    const post = await Post.forceCreate({
      title: 'zzfuture-marker',
      excerpt: 'x',
      body: 'x',
      authorId: 1,
      publishedAt: new Date(Date.now() + 86_400_000).toISOString(),
    })
    const res = await http.query('/posts/search', { keywords: ['zzfuture-marker'] })
    expect(JSON.stringify(await res.response.json())).not.toContain('zzfuture-marker')
    await http.get(`/posts/${post?.id}`).assertStatus(404)
    await Post.delete({ id: post?.id })
  })
})
